import csv
from io import StringIO

def lire_table_csv(texte):
    if type(texte) is not str:
        raise TypeError('texte attendu')
    try:
        return list(csv.reader(StringIO(texte, newline=''), delimiter=';', strict=True))
    except csv.Error:
        raise ValueError('CSV invalide')

